CREATE TABLE IF NOT EXISTS public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL, receiver_id uuid NOT NULL, content text, attachment_url text, attachment_name text, attachment_type text, is_voice boolean DEFAULT false, voice_duration integer, read boolean DEFAULT false, edited boolean DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can view own messages" ON public.messages; DROP POLICY IF EXISTS "Users can insert messages" ON public.messages; DROP POLICY IF EXISTS "Users can update own messages" ON public.messages; DROP POLICY IF EXISTS "Users can delete own messages" ON public.messages;
CREATE POLICY "Users can view own messages" ON public.messages FOR SELECT TO authenticated USING (auth.uid() = sender_id OR auth.uid() = receiver_id);
CREATE POLICY "Users can insert messages" ON public.messages FOR INSERT TO authenticated WITH CHECK (auth.uid() = sender_id AND public.is_staff(auth.uid()));
CREATE POLICY "Users can update own messages" ON public.messages FOR UPDATE TO authenticated USING (auth.uid() = sender_id OR auth.uid() = receiver_id);
CREATE POLICY "Users can delete own messages" ON public.messages FOR DELETE TO authenticated USING (auth.uid() = sender_id);
DROP TRIGGER IF EXISTS update_messages_updated_at ON public.messages; CREATE TRIGGER update_messages_updated_at BEFORE UPDATE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE IF NOT EXISTS public.message_reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL, user_id uuid NOT NULL, emoji text, reaction text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_id, user_id, emoji));
ALTER TABLE public.message_reactions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff can view reactions" ON public.message_reactions; DROP POLICY IF EXISTS "Staff can insert reactions" ON public.message_reactions; DROP POLICY IF EXISTS "Staff can delete own reactions" ON public.message_reactions;
CREATE POLICY "Staff can view reactions" ON public.message_reactions FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff can insert reactions" ON public.message_reactions FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id AND public.is_staff(auth.uid()));
CREATE POLICY "Staff can delete own reactions" ON public.message_reactions FOR DELETE TO authenticated USING (auth.uid() = user_id);

CREATE TABLE IF NOT EXISTS public.team_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL, sender_id uuid NOT NULL, content text, attachment_urls text[] DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.team_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff can view team messages" ON public.team_messages; DROP POLICY IF EXISTS "Staff can send team messages" ON public.team_messages; DROP POLICY IF EXISTS "Senders can delete own messages" ON public.team_messages;
CREATE POLICY "Staff can view team messages" ON public.team_messages FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff can send team messages" ON public.team_messages FOR INSERT TO authenticated WITH CHECK (auth.uid() = sender_id AND public.is_staff(auth.uid()));
CREATE POLICY "Senders can delete own messages" ON public.team_messages FOR DELETE TO authenticated USING (auth.uid() = sender_id);

CREATE TABLE IF NOT EXISTS public.direct_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL, receiver_id uuid NOT NULL, content text, attachment_urls text[] DEFAULT '{}', read boolean DEFAULT false, edited boolean DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.direct_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users view own DMs" ON public.direct_messages; DROP POLICY IF EXISTS "Users send DMs" ON public.direct_messages; DROP POLICY IF EXISTS "Users update own DMs" ON public.direct_messages; DROP POLICY IF EXISTS "Senders delete own DMs" ON public.direct_messages;
CREATE POLICY "Users view own DMs" ON public.direct_messages FOR SELECT TO authenticated USING (auth.uid() = sender_id OR auth.uid() = receiver_id OR public.has_role(auth.uid(),'ceo'));
