CREATE POLICY "Users update own DMs" ON public.direct_messages FOR UPDATE TO authenticated USING (auth.uid() = sender_id OR auth.uid() = receiver_id);
CREATE POLICY "Senders delete own DMs" ON public.direct_messages FOR DELETE TO authenticated USING (auth.uid() = sender_id);
DROP TRIGGER IF EXISTS update_direct_messages_updated_at ON public.direct_messages; CREATE TRIGGER update_direct_messages_updated_at BEFORE UPDATE ON public.direct_messages FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE IF NOT EXISTS public.dm_reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL, user_id uuid NOT NULL, reaction text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
