CREATE POLICY "Executives can insert config" ON public.salary_configs FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR public.has_role(auth.uid(), 'finance_manager'));
CREATE POLICY "Executives can update config" ON public.salary_configs FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR public.has_role(auth.uid(), 'finance_manager'));
CREATE POLICY "Executives can delete config" ON public.salary_configs FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR public.has_role(auth.uid(), 'finance_manager'));

