CREATE POLICY "Executives can update payments" ON public.salary_payments FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR public.has_role(auth.uid(), 'finance_manager'));

