CREATE POLICY "HR can insert warnings" ON public.hr_warnings FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr'));
CREATE POLICY "HR can update warnings" ON public.hr_warnings FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR auth.uid() = staff_id);

CREATE TABLE IF NOT EXISTS public.application_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.job_applications(id) ON DELETE CASCADE, sender_id uuid NOT NULL, sender_role text NOT NULL, content text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_application_messages_application_id ON public.application_messages(application_id);
CREATE INDEX IF NOT EXISTS idx_application_messages_created_at ON public.application_messages(created_at DESC);
ALTER TABLE public.application_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "View application messages" ON public.application_messages; DROP POLICY IF EXISTS "Staff can send application messages" ON public.application_messages; DROP POLICY IF EXISTS "Applicant can reply on own application" ON public.application_messages; DROP POLICY IF EXISTS "Recipients can mark messages read" ON public.application_messages;
CREATE POLICY "View application messages" ON public.application_messages FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR EXISTS (SELECT 1 FROM public.job_applications ja WHERE ja.id = application_id AND ja.user_id = auth.uid()));
CREATE POLICY "Staff can send application messages" ON public.application_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid() AND sender_role = 'staff' AND (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr')));
CREATE POLICY "Applicant can reply on own application" ON public.application_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid() AND sender_role = 'applicant' AND EXISTS (SELECT 1 FROM public.job_applications ja WHERE ja.id = application_id AND ja.user_id = auth.uid()));
CREATE POLICY "Recipients can mark messages read" ON public.application_messages FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr') OR EXISTS (SELECT 1 FROM public.job_applications ja WHERE ja.id = application_id AND ja.user_id = auth.uid()));

CREATE TABLE IF NOT EXISTS public.site_slides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), image_url text NOT NULL, title text, caption text, cta_label text, cta_link text, display_order int NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid);
CREATE INDEX IF NOT EXISTS idx_site_slides_order ON public.site_slides(display_order) WHERE is_active = true; ALTER TABLE public.site_slides ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone can view active slides" ON public.site_slides; DROP POLICY IF EXISTS "Module editors manage slides" ON public.site_slides;
