DROP TRIGGER IF EXISTS update_site_slides_updated_at ON public.site_slides; CREATE TRIGGER update_site_slides_updated_at BEFORE UPDATE ON public.site_slides FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE IF NOT EXISTS public.site_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_name text NOT NULL DEFAULT 'Netlink General Solutions', company_tagline text DEFAULT 'Where Ethiopia''s digital future begins', logo_url text, vision text, mission text, core_values text, welcome_message text DEFAULT 'Welcome to Netlink General Solutions, where Ethiopia''s digital future begins and ambitious organizations find the technology partner they can trust to build bold, move smart, and grow without limits.', founder_name text, founder_title text, founder_message text, founder_photo_url text, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
