CREATE POLICY "Identity editors update settings" ON public.site_settings FOR UPDATE TO authenticated USING (public.has_module_permission(auth.uid(), 'identity')) WITH CHECK (public.has_module_permission(auth.uid(), 'identity'));
CREATE POLICY "Identity editors insert settings" ON public.site_settings FOR INSERT TO authenticated WITH CHECK (public.has_module_permission(auth.uid(), 'identity'));
DROP TRIGGER IF EXISTS update_site_settings_updated_at ON public.site_settings; CREATE TRIGGER update_site_settings_updated_at BEFORE UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.site_settings (company_name) SELECT 'Netlink General Solutions PLC' WHERE NOT EXISTS (SELECT 1 FROM public.site_settings);

