CREATE POLICY "Stats editors manage stats" ON public.site_stats FOR ALL TO authenticated USING (public.has_module_permission(auth.uid(), 'stats')) WITH CHECK (public.has_module_permission(auth.uid(), 'stats'));
DROP TRIGGER IF EXISTS update_site_stats_updated_at ON public.site_stats; CREATE TRIGGER update_site_stats_updated_at BEFORE UPDATE ON public.site_stats FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE IF NOT EXISTS public.visitor_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visitor_hash text NOT NULL UNIQUE, first_seen timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), visit_count integer NOT NULL DEFAULT 1); ALTER TABLE public.visitor_log ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Public can read visitor count" ON public.visitor_log; CREATE POLICY "Public can read visitor count" ON public.visitor_log FOR SELECT USING (true);
CREATE TABLE IF NOT EXISTS public.online_visitors (visitor_hash text PRIMARY KEY, last_ping timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.online_visitors ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Public read online" ON public.online_visitors; CREATE POLICY "Public read online" ON public.online_visitors FOR SELECT USING (true);
CREATE OR REPLACE FUNCTION public.track_visitor(p_hash text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_count bigint; BEGIN INSERT INTO public.visitor_log (visitor_hash) VALUES (p_hash) ON CONFLICT (visitor_hash) DO UPDATE SET last_seen = now(), visit_count = public.visitor_log.visit_count + 1; INSERT INTO public.online_visitors (visitor_hash, last_ping) VALUES (p_hash, now()) ON CONFLICT (visitor_hash) DO UPDATE SET last_ping = now(); SELECT COUNT(*) INTO v_count FROM public.visitor_log; RETURN v_count; END; $$;
CREATE OR REPLACE FUNCTION public.ping_online(p_hash text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.online_visitors (visitor_hash, last_ping) VALUES (p_hash, now()) ON CONFLICT (visitor_hash) DO UPDATE SET last_ping = now(); DELETE FROM public.online_visitors WHERE last_ping < now() - interval '5 minutes'; END; $$;
CREATE OR REPLACE FUNCTION public.get_online_count() RETURNS bigint LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$ SELECT COUNT(*) FROM public.online_visitors WHERE last_ping > now() - interval '5 minutes' $$;
CREATE OR REPLACE FUNCTION public.get_subscriber_count() RETURNS bigint LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$ SELECT COUNT(*) FROM public.subscriber_emails WHERE subscribed = true $$;
GRANT EXECUTE ON FUNCTION public.track_visitor(text) TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.ping_online(text) TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.get_online_count() TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.get_subscriber_count() TO anon, authenticated;

CREATE TABLE IF NOT EXISTS public.content_likes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES public.site_content(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(content_id, user_id)); ALTER TABLE public.content_likes ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Anyone can view likes" ON public.content_likes; DROP POLICY IF EXISTS "Authenticated can like" ON public.content_likes; DROP POLICY IF EXISTS "Users can unlike own" ON public.content_likes; CREATE POLICY "Anyone can view likes" ON public.content_likes FOR SELECT USING (true); CREATE POLICY "Authenticated can like" ON public.content_likes FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can unlike own" ON public.content_likes FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE TABLE IF NOT EXISTS public.content_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES public.site_content(id) ON DELETE CASCADE, user_id uuid NOT NULL, author_name text NOT NULL DEFAULT '', body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.content_comments ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Anyone can view comments" ON public.content_comments; DROP POLICY IF EXISTS "Authenticated can comment" ON public.content_comments; DROP POLICY IF EXISTS "Author or staff can delete" ON public.content_comments; CREATE POLICY "Anyone can view comments" ON public.content_comments FOR SELECT USING (true); CREATE POLICY "Authenticated can comment" ON public.content_comments FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Author or staff can delete" ON public.content_comments FOR DELETE TO authenticated USING (auth.uid() = user_id OR public.has_role(auth.uid(), 'ceo') OR public.has_role(auth.uid(), 'hr'));
CREATE TABLE IF NOT EXISTS public.content_reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES public.site_content(id) ON DELETE CASCADE, user_id uuid NOT NULL, reaction text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(content_id, user_id, reaction)); ALTER TABLE public.content_reactions ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Anyone can view reactions" ON public.content_reactions; DROP POLICY IF EXISTS "Authenticated can react" ON public.content_reactions; DROP POLICY IF EXISTS "Users can remove own reaction" ON public.content_reactions; CREATE POLICY "Anyone can view reactions" ON public.content_reactions FOR SELECT USING (true); CREATE POLICY "Authenticated can react" ON public.content_reactions FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can remove own reaction" ON public.content_reactions FOR DELETE TO authenticated USING (auth.uid() = user_id);

CREATE INDEX IF NOT EXISTS idx_employee_profiles_user_id ON public.employee_profiles(user_id); CREATE INDEX IF NOT EXISTS idx_employee_qualifications_user_id ON public.employee_qualifications(user_id); CREATE INDEX IF NOT EXISTS idx_employee_documents_user_id ON public.employee_documents(user_id); CREATE INDEX IF NOT EXISTS idx_experience_letters_user_id ON public.experience_letters(user_id); CREATE INDEX IF NOT EXISTS idx_experience_letters_status ON public.experience_letters(status); CREATE INDEX IF NOT EXISTS idx_employee_audit_log_user_id ON public.employee_audit_log(user_id); CREATE INDEX IF NOT EXISTS idx_attendance_user_id ON public.attendance(user_id); CREATE INDEX IF NOT EXISTS idx_attendance_clock_in ON public.attendance(clock_in); CREATE INDEX IF NOT EXISTS idx_leave_requests_user_id ON public.leave_requests(user_id); CREATE INDEX IF NOT EXISTS idx_plans_author_id ON public.plans(author_id); CREATE INDEX IF NOT EXISTS idx_messages_sender ON public.messages(sender_id); CREATE INDEX IF NOT EXISTS idx_messages_receiver ON public.messages(receiver_id); CREATE INDEX IF NOT EXISTS idx_salary_configs_staff ON public.salary_configs(staff_id); CREATE INDEX IF NOT EXISTS idx_salary_payments_staff ON public.salary_payments(staff_id); CREATE INDEX IF NOT EXISTS idx_performance_records_staff ON public.performance_records(staff_id); CREATE INDEX IF NOT EXISTS idx_hr_warnings_staff ON public.hr_warnings(staff_id); CREATE INDEX IF NOT EXISTS idx_hr_warnings_month ON public.hr_warnings(month);

